begin read only;
set local statement_timeout='8s';
with scope as (select 'cffc2183-e77c-4148-a206-d5192e090925'::uuid bid,'b3e8c006-c250-4b50-9524-24d3508d31d2'::uuid tid)
select jsonb_build_object(
 'captured_at',statement_timestamp(),
 'ledger',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations),
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'config',p.proconfig,'definer',p.prosecdef,'body',p.prosrc) order by p.oid::regprocedure::text) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('reconcile_undone_split_pre_provider','reject_posting_before_provider','undo_split_categorization','assert_canonical_manual_actor','lock_bookkeeping_exclusion_identity')),
 'actors',(select jsonb_agg(user_id) from public.internal_staff_users where active and role in ('owner_admin','accountant','operator')),
 'category',(select jsonb_build_object('status',c.status,'review_status',c.review_status,'posting_status',c.posting_status,'post_after',c.post_after,'post_error',c.post_error,'final_qbo_account_id',c.final_qbo_account_id,'qbo_txn_id',c.qbo_txn_id,'posted_at',c.posted_at,'review_reopened_at',c.review_reopened_at,'review_reopen_reason',c.review_reopen_reason,'updated_at',c.updated_at,'meta',c.meta) from public.transaction_categorizations c,scope x where c.business_id=x.bid and c.transaction_id=x.tid),
 'intent',(select jsonb_build_object('id',i.id,'status',i.status,'request_id',i.request_id,'idempotency_key',i.idempotency_key,'attempt_count',i.attempt_count,'processing_started_at',i.processing_started_at,'lease_expires_at',i.lease_expires_at,'qbo_txn_id',i.qbo_txn_id,'has_response',i.response is not null,'response_summary',i.response_summary) from public.qbo_posted_transactions i,scope x where i.business_id=x.bid and i.transaction_id=x.tid),
 'job',(select to_jsonb(j) from public.bookkeeping_posting_jobs j,scope x where j.business_id=x.bid and j.transaction_id=x.tid),
 'attempts',(select jsonb_agg(to_jsonb(a) order by a.attempted_at) from public.bookkeeping_post_attempts a,scope x where a.business_id=x.bid and a.transaction_id=x.tid),
 'context',(select jsonb_build_object('business_id',c.business_id,'transaction_id',c.transaction_id,'env',i.qbo_env,'realm_id',i.realm_id,'owner',c.meta->>'posting_execution_owner','request_id',i.request_id,'idempotency_key',i.idempotency_key,'generation',c.meta->>'posting_generation','claimed_at',i.processing_started_at,'lease_expires_at',i.lease_expires_at,'category_updated_at',c.updated_at,'review_reopened_at',c.review_reopened_at,'intent_id',i.id,'job_id',j.id,'attempt_id',a.id,'split_id',s.id,'split_lines_hash',encode(sha256(convert_to(s.lines::text,'UTF8')),'hex')) from public.transaction_categorizations c join public.qbo_posted_transactions i using(business_id,transaction_id) join public.bookkeeping_posting_jobs j using(business_id,transaction_id) join public.transaction_splits s using(business_id,transaction_id) join public.bookkeeping_post_attempts a using(business_id,transaction_id),scope x where c.business_id=x.bid and c.transaction_id=x.tid and s.status='confirmed' order by a.attempted_at limit 1)
) as catalog;
rollback;
